widget.solution:
def steps_a(n):
    steps = 0
    for i in range(n):
        steps += 50
    return steps


def steps_b(n):
    steps = 0
    for i in range(n):
        for j in range(n):
            steps += 1
    return steps


def cheaper(n):
    a, b = steps_a(n), steps_b(n)
    if a < b:
        return "A"
    if b < a:
        return "B"
    return "tie"

